import{_ as t,C as a,c as r,o as e,j as n,G as i,b as l,a0 as s,a as o,w as d,a1 as g}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"Näring för precisionsprestanda","description":"","frontmatter":{},"headers":[],"relativePath":"sv/education/nutrition/index.md","filePath":"sv/education/nutrition/index.md"}');const p=t({name:"sv/education/nutrition/index.md"},[["render",function(t,k,p,m,h,u){const c=a("AdBanner"),v=a("Mermaid"),b=a("AdInArticle");return e(),r("div",null,[k[2]||(k[2]=n("h1",{id:"naring-for-precisionsprestanda",tabindex:"-1"},[o("Näring för precisionsprestanda "),n("a",{class:"header-anchor",href:"#naring-for-precisionsprestanda","aria-label":'Permalink to "Näring för precisionsprestanda"'},"​")],-1)),i(c),k[3]||(k[3]=n("p",null,[o("Boule är en precisionssport, inte en uthållighetssport. Dina näringsbehov skiljer sig från en maratonlöpares eller en fotbollsspelares. Det som är viktigast är "),n("strong",null,"stabilitet i hjärnans bränsle"),o(" – att hålla ditt sinne skarpt och dina händer stadiga under en lång tävlingsdag.")],-1)),k[4]||(k[4]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Den stora idén"),n("p",null,[n("strong",null,"Din hjärna är ditt viktigaste verktyg i boule. Ge den stabil bränsle, inte berg-och-dalbaneenergi."),o(" Fokusera på protein, hälsosamma fetter och att hålla dig hydrerad. Undvik sockertoppar.")])],-1)),(e(),l(g,null,{default:d(()=>[i(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BSocker%2Fenkla%20kolhydrater%5D%20--%3E%20B%5BBlodsockertopp%5D%0A%20%20%20%20B%20--%3E%20C%5BInsulinfris%C3%A4ttning%5D%0A%20%20%20%20C%20--%3E%20D%5BBlodsockerkrasch%5D%0A%20%20%20%20D%20--%3E%20E%5BAdrenalinrespons%5D%0A%20%20%20%20E%20--%3E%20F%5BSkakningar%20och%20%C3%A5ngest%5D%0A%0A%20%20%20%20G%5BProtein%20och%20h%C3%A4lsosamma%20fetter%5D%20--%3E%20H%5BStabilt%20blodsocker%5D%0A%20%20%20%20H%20--%3E%20I%5BKonsekvent%20energi%5D%0A%20%20%20%20I%20--%3E%20J%5BSkarpt%20fokus%5D%0A%20%20%20%20J%20--%3E%20K%5BStadiga%20h%C3%A4nder%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:d(()=>[...k[0]||(k[0]=[o(" Loading... ",-1)])]),_:1})),k[5]||(k[5]=s('<h2 id="precisionsidrottarens-utmaning" tabindex="-1">Precisionsidrottarens utmaning <a class="header-anchor" href="#precisionsidrottarens-utmaning" aria-label="Permalink to &quot;Precisionsidrottarens utmaning&quot;">​</a></h2><p>Till skillnad från högintensiva sporter kräver inte boule massiva glykogenlager eller snabb energipåfyllning. Det som krävs är:</p><ul><li><strong>Stabilt blodsocker</strong> - inga toppar eller krascher</li><li><strong>Konsekvent mental klarhet</strong> - fokus som varar hela dagen</li><li><strong>Stadig hand</strong> - inga skakningar eller skakningar</li><li><strong>Lugna nerverna</strong> - låg ångest och stressreaktion</li></ul><p>Din näringsstrategi bör optimera för dessa faktorer, inte för rå energiproduktion.</p><h2 id="problemet-med-socker-och-enkla-kolhydrater" tabindex="-1">Problemet med socker och enkla kolhydrater <a class="header-anchor" href="#problemet-med-socker-och-enkla-kolhydrater" aria-label="Permalink to &quot;Problemet med socker och enkla kolhydrater&quot;">​</a></h2><p>Många idrottare väljer en kolhydratrik diet som standard. För boulespelare kan detta faktiskt försämra prestationen.</p><h3 id="blodsockrets-berg-och-dalbana" tabindex="-1">Blodsockrets berg-och-dalbana <a class="header-anchor" href="#blodsockrets-berg-och-dalbana" aria-label="Permalink to &quot;Blodsockrets berg-och-dalbana&quot;">​</a></h3><p>När du äter socker eller enkla kolhydrater:</p><ol><li>Blodsockret stiger snabbt</li><li>Insulin frisätts för att sänka det</li><li>Blodsockret sjunker (hypoglykemi)</li><li>Din kropp frigör adrenalin för att kompensera</li><li>Du upplever skakningar, ångest och dålig fokus</li></ol><p><strong>Detta är motsatsen till vad du behöver för precision.</strong></p><h3 id="symtom-pa-blodsockerinstabilitet" tabindex="-1">Symtom på blodsockerinstabilitet <a class="header-anchor" href="#symtom-pa-blodsockerinstabilitet" aria-label="Permalink to &quot;Symtom på blodsockerinstabilitet&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Påverkan på prestanda</th></tr></thead><tbody><tr><td>Darrande händer</td><td>Inkonsekvent utgåva</td></tr><tr><td>Koncentrationssvårigheter</td><td>Dåligt beslutsfattande</td></tr><tr><td>Irritabilitet</td><td>Lagkonflikt, dåligt lugn</td></tr><tr><td>Trötthet efter måltider</td><td>Eftermiddagssvacka</td></tr><tr><td>Ångest</td><td>Tryckkänslighet</td></tr><tr><td>Hjärndimma</td><td>Långsamt taktiskt tänkande</td></tr></tbody></table><h2 id="en-battre-metod-stabil-energi" tabindex="-1">En bättre metod: Stabil energi <a class="header-anchor" href="#en-battre-metod-stabil-energi" aria-label="Permalink to &quot;En bättre metod: Stabil energi&quot;">​</a></h2><p>Målet är att förse din hjärna med regelbundet bränsle utan berg-och-dalbanan.</p><h3 id="viktiga-principer" tabindex="-1">Viktiga principer <a class="header-anchor" href="#viktiga-principer" aria-label="Permalink to &quot;Viktiga principer&quot;">​</a></h3><ol><li><strong>Prioritera protein och hälsosamma fetter</strong> - De ger långsam, stadig energi</li><li><strong>Välj komplexa kolhydrater framför enkla</strong> - Om du äter kolhydrater, välj de som smälter långsamt</li><li><strong>Undvik sockertoppar</strong> - Speciellt före och under tävling</li><li><strong>Håll dig hydrerad</strong> - Uttorkning påverkar koncentrationen avsevärt</li><li><strong>Ät regelbundet</strong> - Låt dig inte bli för hungrig</li></ol><h3 id="livsmedel-som-hjalper" tabindex="-1">Livsmedel som hjälper <a class="header-anchor" href="#livsmedel-som-hjalper" aria-label="Permalink to &quot;Livsmedel som hjälper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mattyp</th><th>Exempel</th><th>Varför det fungerar</th></tr></thead><tbody><tr><td>Protein</td><td>Ägg, nötter, ost, kött</td><td>Långsam matsmältning, stabil energi</td></tr><tr><td>Hälsosamma fetter</td><td>Avokado, olivolja, nötter</td><td>Långvarigt bränsle</td></tr><tr><td>Komplexa kolhydrater</td><td>Grönsaker, baljväxter</td><td>Fiber saktar upptaget</td></tr><tr><td>Frukter med lågt sockerinnehåll</td><td>Bär, äpplen</td><td>Näringsämnen utan spik</td></tr></tbody></table><h3 id="livsmedel-att-begransa" tabindex="-1">Livsmedel att begränsa <a class="header-anchor" href="#livsmedel-att-begransa" aria-label="Permalink to &quot;Livsmedel att begränsa&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mattyp</th><th>Exempel</th><th>Varför det är problematiskt</th></tr></thead><tbody><tr><td>Socker</td><td>Godis, läsk, bakverk</td><td>Snabb topp och krasch</td></tr><tr><td>Vitt bröd/pasta</td><td>Smörgåsar, pastarätter</td><td>Snabb omvandling till socker</td></tr><tr><td>Fruktjos</td><td>Apelsinjuice, smoothies</td><td>Koncentrerat socker</td></tr><tr><td>Energidrycker</td><td>De flesta kommersiella varumärken</td><td>Socker + koffein-krasch</td></tr></tbody></table><h2 id="naringslara-pa-tavlingsdagen" tabindex="-1">Näringslära på tävlingsdagen <a class="header-anchor" href="#naringslara-pa-tavlingsdagen" aria-label="Permalink to &quot;Näringslära på tävlingsdagen&quot;">​</a></h2><h3 id="fore-tavlingen" tabindex="-1">Före tävlingen <a class="header-anchor" href="#fore-tavlingen" aria-label="Permalink to &quot;Före tävlingen&quot;">​</a></h3><p><strong>2–3 timmar innan:</strong></p><ul><li>Balanserad måltid med protein, fett och grönsaker</li><li>Undvik tunga kolhydrater som kan orsaka dåsighet</li><li>Exempel: Ägg med grönsaker, eller sallad med kyckling</li></ul><p><strong>1 timme innan:</strong></p><ul><li>Lättare mellanmål om det behövs</li><li>Nötter, ost eller en liten portion protein</li><li>Undvik allt som är sockerartat</li></ul><h3 id="under-tavlingen" tabindex="-1">Under tävlingen <a class="header-anchor" href="#under-tavlingen" aria-label="Permalink to &quot;Under tävlingen&quot;">​</a></h3><p><strong>Mellan spelen:</strong></p><ul><li>Vatten (viktigast)</li><li>Små proteinsnacks (nötter, ost, kött)</li><li>Undvik söta snacks och drycker</li></ul><p><strong>Tecken på att du behöver äta:</strong></p><ul><li>Koncentrationssvårigheter</li><li>Irritabilitet</li><li>Känsla av skakighet</li><li>Huvudvärk</li></ul><h3 id="efter-tavlingen" tabindex="-1">Efter tävlingen <a class="header-anchor" href="#efter-tavlingen" aria-label="Permalink to &quot;Efter tävlingen&quot;">​</a></h3><ul><li>Fyll på med en balanserad måltid</li><li>Rehydrera helt</li><li>&quot;Belöna&quot; inte dig själv med socker – det kommer att påverka din återhämtning</li></ul><h2 id="hydrering" tabindex="-1">Hydrering <a class="header-anchor" href="#hydrering" aria-label="Permalink to &quot;Hydrering&quot;">​</a></h2><p>Uttorkning påverkar kognitiv funktion innan du känner dig törstig.</p><h3 id="riktlinjer" tabindex="-1">Riktlinjer <a class="header-anchor" href="#riktlinjer" aria-label="Permalink to &quot;Riktlinjer&quot;">​</a></h3><ul><li><strong>Börja med att dricka vätska</strong> - Drick vatten under dagen före tävlingen</li><li><strong>Under lek</strong> - Drick vatten regelbundet, vänta inte tills du är törstig</li><li><strong>Undvik överskott av koffein</strong> - Det är ett vätskedrivande medel</li><li><strong>Var uppmärksam på tecken</strong> - Huvudvärk, mörk urin, trötthet</li></ul><h3 id="hur-mycket" tabindex="-1">Hur mycket? <a class="header-anchor" href="#hur-mycket" aria-label="Permalink to &quot;Hur mycket?&quot;">​</a></h3><p>En allmän riktlinje: sikta på ljusgul urin. Om den är mörk behöver du mer vatten.</p><h2 id="lagkolhydratalternativet" tabindex="-1">Lågkolhydratalternativet <a class="header-anchor" href="#lagkolhydratalternativet" aria-label="Permalink to &quot;Lågkolhydratalternativet&quot;">​</a></h2><p>Vissa precisionsidrottare använder sig av lågkolhydratkost eller ketogen kost. Teorin:</p><p><strong>Potentiella fördelar:</strong></p><ul><li>Mycket stabilt blodsocker (inga toppar möjliga)</li><li>Konsekvent mental klarhet</li><li>Minskad ångest och skakningar</li><li>Inga energikrascher på eftermiddagen</li></ul><p><strong>Att tänka på:</strong></p><ul><li>Kräver anpassningsperiod (1-2 veckor)</li><li>Inte lämplig för alla</li><li>Kräver planering och engagemang</li><li>Rådfråga en vårdgivare först</li></ul>',45)),i(b),k[6]||(k[6]=s('<p>Detta är en avancerad strategi – inte nödvändig för alla, men värd att överväga om blodsockrets stabilitet är ett betydande problem för dig.</p><h2 id="mat-som-ovning-trana-din-kropp" tabindex="-1">Mat som övning: Träna din kropp <a class="header-anchor" href="#mat-som-ovning-trana-din-kropp" aria-label="Permalink to &quot;Mat som övning: Träna din kropp&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Kritiskt koncept</p><p><strong>Mat är inte bara bränsle – det är något man tränar med.</strong> Precis som du tränar ditt kast måste du öva på din kost för att din kropp ska bli bekväm med att äta på tävlingsdagen.</p></div><h3 id="varfor-livsmedelsrutiner-ar-viktiga" tabindex="-1">Varför livsmedelsrutiner är viktiga <a class="header-anchor" href="#varfor-livsmedelsrutiner-ar-viktiga" aria-label="Permalink to &quot;Varför livsmedelsrutiner är viktiga&quot;">​</a></h3><p>Ditt matsmältningssystem är träningsbart. Det du äter regelbundet blir vad din kropp förväntar sig och hanterar bäst. Om du bara äter protein och grönsaker på tävlingsdagar kommer din kropp inte att anpassa sig till det.</p><p><strong>Problemet:</strong></p><ul><li>Att äta obekant mat på tävlingsdagen kan orsaka matsmältningsbesvär</li><li>Din kropp behöver tid för att anpassa sig till nya matvanor</li><li>Stress + obekant mat = potentiella magproblem</li><li>Prestationsångest är tillräckligt dålig utan att det ger matsmältningsångest</li></ul><p><strong>Lösningen:</strong></p><ul><li>Öva på din tävlingskost under träningen</li><li>Gör din tävlingsdagsmat till en del av din vanliga rutin</li><li>Träna din kropp att vara bekväm med mat med stabil energi</li></ul><h3 id="anpassningsprocessen" tabindex="-1">Anpassningsprocessen <a class="header-anchor" href="#anpassningsprocessen" aria-label="Permalink to &quot;Anpassningsprocessen&quot;">​</a></h3>',10)),(e(),l(g,null,{default:d(()=>[i(v,{id:"mermaid-590",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BNuvarande%20kost%5D%20--%3E%20B%5BGradvisa%20f%C3%B6r%C3%A4ndringar%5D%0A%20%20%20%20B%20--%3E%20C%5BKroppsanpassning%20%3Cbr%2F%3E%202%E2%80%934%20veckor%5D%0A%20%20%20%20C%20--%3E%20D%5BNy%20normalitet%5D%0A%20%20%20%20D%20--%3E%20E%5BRedo%20f%C3%B6r%20t%C3%A4vling%5D%0A%0A%20%20%20%20F%5BPl%C3%B6tslig%20f%C3%B6r%C3%A4ndring%20%3Cbr%2F%3E%20T%C3%A4vlingsdag%5D%20--%3E%20G%5BMatsm%C3%A4ltningsbesv%C3%A4r%5D%0A%20%20%20%20G%20--%3E%20H%5BD%C3%A5lig%20prestanda%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:d(()=>[...k[1]||(k[1]=[o(" Loading... ",-1)])]),_:1})),k[7]||(k[7]=s('<p>När du ändrar din kost:</p><ol><li><strong>Vecka 1-2:</strong> Din kropp anpassar sig till nya livsmedel, kan kännas annorlunda</li><li><strong>Vecka 3-4:</strong> Anpassning sker, nya livsmedel känns normala</li><li><strong>Vecka 5+:</strong> Din kropp mår bra och är effektiv med dessa livsmedel</li></ol><p><strong>Det är därför du inte bara kan &quot;äta hälsosamt&quot; på tävlingsdagen och förvänta dig optimala resultat.</strong></p><h3 id="hur-du-ovar-din-kost" tabindex="-1">Hur du övar din kost <a class="header-anchor" href="#hur-du-ovar-din-kost" aria-label="Permalink to &quot;Hur du övar din kost&quot;">​</a></h3><h4 id="_1-borja-under-traningen" tabindex="-1">1. Börja under träningen <a class="header-anchor" href="#_1-borja-under-traningen" aria-label="Permalink to &quot;1. Börja under träningen&quot;">​</a></h4><p><strong>Öva på din tävlingsdagsmat under träningspassen:</strong></p><ul><li>Ät samma måltid före träning som du skulle äta före tävling</li><li>Ta med samma snacks som du skulle ta med till en tävling</li><li>Lägg märke till hur din kropp reagerar</li><li>Anpassa utifrån vad som fungerar</li></ul><p><strong>Exempel på träningsdag:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-gor-det-till-ditt-normala" tabindex="-1">2. Gör det till ditt normala <a class="header-anchor" href="#_2-gor-det-till-ditt-normala" aria-label="Permalink to &quot;2. Gör det till ditt normala&quot;">​</a></h4><p><strong>Inte ha en &quot;tävlingsdiet&quot; och en &quot;vanlig diet&quot;</strong> – detta skapar två problem:</p><ul><li>Din kropp anpassar sig aldrig helt till någon av dem</li><li>Tävlingsmat känns obekant och stressigt</li></ul><p><strong>I stället:</strong></p><ul><li>Gör mat med stabil energi till din dagliga norm</li><li>Din kropp blir effektivare på att använda protein och fett</li><li>Tävlingsdagen känns normal, inte annorlunda</li><li>Inga överraskningar i matsmältningen</li></ul><h4 id="_3-testa-och-forfina" tabindex="-1">3. Testa och förfina <a class="header-anchor" href="#_3-testa-och-forfina" aria-label="Permalink to &quot;3. Testa och förfina&quot;">​</a></h4><p><strong>Använd träning för att experimentera:</strong></p><table tabindex="0"><thead><tr><th>Testa</th><th>Vad man bör lägga märke till</th><th>Justera</th></tr></thead><tbody><tr><td>Måltider före träning</td><td>Energinivåer, fokus</td><td>Hitta ditt optimala fönster</td></tr><tr><td>Olika proteinkällor</td><td>Matsmältning, komfort</td><td>Identifiera vad som fungerar bäst</td></tr><tr><td>Mellanmålstyper</td><td>Hållbar energi</td><td>Hitta dina favoritsnacks</td></tr><tr><td>Hydreringsmängder</td><td>Koncentration, toalettpauser</td><td>Balansintag</td></tr></tbody></table><p><strong>För en enkel logg:</strong></p><ul><li>Vad du åt och när</li><li>Hur du kände dig under träningen</li><li>Energinivåer och fokus</li><li>Eventuella matsmältningsproblem</li></ul><h4 id="_4-bygg-komfort-och-sjalvfortroende" tabindex="-1">4. Bygg komfort och självförtroende <a class="header-anchor" href="#_4-bygg-komfort-och-sjalvfortroende" aria-label="Permalink to &quot;4. Bygg komfort och självförtroende&quot;">​</a></h4><p><strong>Den psykologiska fördelen:</strong></p><p>När du har övat på din kost hundratals gånger under träning:</p><ul><li>Du vet exakt hur din kropp kommer att reagera</li><li>Ingen oro över matval</li><li>En sak mindre att oroa sig för på tävlingsdagen</li><li>Förtroende för dina förberedelser</li></ul><p><strong>Detta är samma princip som att öva ditt kast</strong> – repetition bygger komfort och pålitlighet.</p><h3 id="vanliga-anpassningsutmaningar" tabindex="-1">Vanliga anpassningsutmaningar <a class="header-anchor" href="#vanliga-anpassningsutmaningar" aria-label="Permalink to &quot;Vanliga anpassningsutmaningar&quot;">​</a></h3><details class="details custom-block"><summary>Övergång från högkolhydratkost till stabil energikost</summary><p><strong>Utmaning:</strong> Du är van vid bröd, pasta och söta snacks</p><p><strong>Anpassningsperiod:</strong> 2–4 veckor</p><p><strong>Vad du kan förvänta dig:</strong></p><ul><li>Vecka 1: Kan kännas annorlunda, sug efter gammal mat</li><li>Vecka 2: Energin stabiliseras, suget minskar</li><li>Vecka 3-4: Nytt normalvärde, kroppen effektiv med fett/protein</li></ul><p><strong>Hur man övar:</strong></p><ul><li>Börja med en måltid i taget</li><li>Byt först ut enkla kolhydrater mot komplexa kolhydrater</li><li>Öka gradvis protein och hälsosamma fetter</li><li>Öva först under träning med låga insatser</li></ul></details><details class="details custom-block"><summary>Att hitta mat som fungerar för dig</summary><p><strong>Utmaning:</strong> Alla smälter inte samma mat lika bra</p><p><strong>Vad ska testa:</strong></p><ul><li>Olika proteinkällor (ägg kontra kött kontra nötter)</li><li>Måltidernas tidpunkt (2 timmar vs. 3 timmar före)</li><li>Portionsstorlekar (för mycket = trög, för lite = hungrig)</li><li>Specifika livsmedel som orsakar obehag</li></ul><p><strong>Övningsmetod:</strong></p><ul><li>Testa en variabel i taget</li><li>Ge varje test 2–3 träningstillfällen</li><li>Notera vad som får dig att må bäst</li><li>Skapa din personliga &quot;tävlingsmeny&quot;</li></ul></details><details class="details custom-block"><summary>Att hantera turneringsmatmiljöer</summary><p><strong>Utmaning:</strong> Turneringar har ofta begränsade matalternativ</p><p><strong>Övningslösning:</strong></p><ul><li>Ta alltid med egna snacks (öva på detta)</li><li>Undersök platser i förväg när det är möjligt</li><li>Ha reservalternativ som du vet fungerar</li><li>Öva på att äta i olika miljöer</li></ul><p><strong>Mental förberedelse:</strong></p><ul><li>Lita inte på maten på stället</li><li>Behandla mat som en del av din utrustning</li><li>Packa det som du packar dina boulebollar</li></ul></details><h3 id="_30-dagars-kostplan" tabindex="-1">30-dagars kostplan <a class="header-anchor" href="#_30-dagars-kostplan" aria-label="Permalink to &quot;30-dagars kostplan&quot;">​</a></h3><p><strong>Mål:</strong> Gör stabil energikost till din bekväma vardag</p><p><strong>Vecka 1-2: Grunden</strong></p><ul><li>Ersätt en måltid per dag med tävlingsliknande måltider</li><li>Öva på kost före träning</li><li>Börja ta med snacks till träningen</li><li>Lägg märke till hur din kropp reagerar</li></ul><p><strong>Vecka 3-4: Utökning</strong></p><ul><li>Gör två måltider per dag stabilt energifokuserade</li><li>Öva på att äta hela tävlingsdagen på träningsdagarna</li><li>Förfina dina mellanmålsval</li><li>Skapa din lista över maträtter</li></ul><p><strong>Vecka 5+: Mästerskap</strong></p><ul><li>Stabil energiätning är din nya normalitet</li><li>Kroppen är helt anpassad</li><li>Tävlingsdagen känns rutinmässig</li><li>Förtroende för din kost</li></ul><h3 id="ditt-tavlingsmatkit" tabindex="-1">Ditt tävlingsmatkit <a class="header-anchor" href="#ditt-tavlingsmatkit" aria-label="Permalink to &quot;Ditt tävlingsmatkit&quot;">​</a></h3><p><strong>Öva på att packa detta inför varje träningspass:</strong></p><p><strong>Före tävling (2-3 timmar innan):</strong></p><ul><li>[ ] Proteinkälla (ägg, kött eller nötter)</li><li>[ ] Grönsaker eller sallad</li><li>[ ] Hälsosamt fett (avokado, olivolja, ost)</li></ul><p><strong>Under tävling:</strong></p><ul><li>[ ] Vattenflaska (påfyllningsbar)</li><li>[ ] Blandade nötter (små portioner)</li><li>[ ] Hårdkokta ägg (om du kan hålla dig sval)</li><li>[ ] Ostbitar eller oststrängar</li><li>[ ] Jerky eller torkat kött</li><li>[ ] Reservsnacks</li></ul><p><strong>Ju mer du övar med det här kitet, desto mer automatiskt blir det.</strong></p><h2 id="praktiska-tips" tabindex="-1">Praktiska tips <a class="header-anchor" href="#praktiska-tips" aria-label="Permalink to &quot;Praktiska tips&quot;">​</a></h2><h3 id="enkla-tavlingssnacks" tabindex="-1">Enkla tävlingssnacks <a class="header-anchor" href="#enkla-tavlingssnacks" aria-label="Permalink to &quot;Enkla tävlingssnacks&quot;">​</a></h3><ul><li>Blandade nötter (osaltade)</li><li>Hårdkokta ägg</li><li>Ostbitar</li><li>Jerky nötkött eller kalkon</li><li>Grönsaker med hummus</li><li>Oliver</li></ul><h3 id="vad-man-ska-undvika" tabindex="-1">Vad man ska undvika <a class="header-anchor" href="#vad-man-ska-undvika" aria-label="Permalink to &quot;Vad man ska undvika&quot;">​</a></h3><ul><li>Snacksautomater</li><li>Sockrade sportdrycker</li><li>Bakverk och bakverk</li><li>Godis- och chokladkakor</li><li>De flesta &quot;energibars&quot; (kontrollera sockerhalten)</li></ul><h2 id="viktig-slutsats" tabindex="-1">Viktig slutsats <a class="header-anchor" href="#viktig-slutsats" aria-label="Permalink to &quot;Viktig slutsats&quot;">​</a></h2><blockquote><p>Din hjärna är ditt viktigaste verktyg i boule. Ge den stabil bränsle, inte berg-och-dalbaneenergi. Och öva på din kost precis som du övar ditt kast – repetition bygger komfort och pålitlighet.</p></blockquote><p>Fokusera på protein, hälsosamma fetter och att hålla dig hydrerad. Undvik sockertoppar. <strong>Viktigast av allt: gör din tävlingsdagskost till din dagliga kost.</strong> Din kropp behöver träning för att prestera som bäst.</p><p><strong>Kom ihåg:</strong> Du skulle inte dyka upp till en turnering med en kastteknik du aldrig har övat på. Kom inte heller upp med en näringsstrategi du aldrig har övat på.</p>',52)),i(c)])}]]);export{k as __pageData,p as default};
